window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5c2ac585f1c694ce"]={"versions": [{"id": "FIG-5c2ac585f1c694ce", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-Aktivitätsdiagramm (Software & Systems Process Engineering Metamodel) aus der AUTOSAR-Methodik (<code>AUTOSAR_TR_Methodology</code>). Dargestellt ist der Teilschritt „Define Network Management“ innerhalb des Systementwurfsprozesses zur Definition netzwerkweiter Management-Mechanismen und deren Zuordnung zu Topologie und Kommunikationsschichten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Rolle</strong>: <code>System Engineer</code> (Akteur/Prozessrolle, verknüpft über Stereotyp <code>«performs»</code>).</li>\n<li><strong>Aktivität</strong>: <code>Define Network Management</code> (Task Definition).</li>\n<li><strong>Eingangs-Artefakte</strong>:</li>\n<li><code>Topology</code> (Kardinalität <code>1</code>, Stereotyp <code>«input»</code>): Beschreibung der physikalischen Netzwerktopologie und Steuergeräte-Vernetzung.</li>\n<li><code>Interaction Layer</code> (Kardinalität <code>0..1</code>, Stereotyp <code>«input»</code>): Optionale Spezifikation der Interaktionsschicht / Kommunikationsbeziehungen.</li>\n<li><strong>Ausgangs-Artefakt</strong>:</li>\n<li><code>Network Layer</code> (Stereotyp <code>«output»</code>): Konfigurationsartefakt bzw. Teilmodell der Netzwerkschicht inklusive Network-Management-Parametern.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der <code>System Engineer</code> führt die Aktivität <code>Define Network Management</code> aus.</li>\n<li>Als zwingende Eingangsgröße wird genau eine Instanz der <code>Topology</code> herangezogen (<code>1 «input»</code>).</li>\n<li>Optional kann eine Spezifikation des <code>Interaction Layer</code> (<code>0..1 «input»</code>) eingebunden werden.</li>\n<li>Als Resultat der Aktivität wird das Artefakt <code>Network Layer</code> erzeugt (<code>«output»</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Kardinalität <code>1</code> fordert das Vorhandensein einer definierten Topologie als zwingende Voraussetzung für die Konfiguration des Network Managements. Das Artefakt <code>Interaction Layer</code> ist mit <code>0..1</code> optional, wodurch eine Festlegung des Network Managements auch vor oder unabhängig von detaillierten Interaktionsschicht-Parametern methodisch zulässig ist. Das resultierende Artefakt <code>Network Layer</code> bildet die Grundlage für nachgelagerte ECU-Extraktions- und Generierungsschritte im AUTOSAR-Workflow.</p>"}, {"id": "FIG-0629dc981f72def3", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-Aktivitätsdiagramm (Software & Systems Process Engineering Metamodel) aus der AUTOSAR-Methodik (<code>AUTOSAR_TR_Methodology</code>). Dargestellt ist der Teilschritt „Define Network Management“ innerhalb des Systementwurfsprozesses zur Definition netzwerkweiter Management-Mechanismen und deren Zuordnung zu Topologie und Kommunikationsschichten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Rolle</strong>: <code>System Engineer</code> (Akteur/Prozessrolle, verknüpft über Stereotyp <code>«performs»</code>).</li>\n<li><strong>Aktivität</strong>: <code>Define Network Management</code> (Task Definition).</li>\n<li><strong>Eingangs-Artefakte</strong>:</li>\n<li><code>Topology</code> (Kardinalität <code>1</code>, Stereotyp <code>«input»</code>): Beschreibung der physikalischen Netzwerktopologie und Steuergeräte-Vernetzung.</li>\n<li><code>Interaction Layer</code> (Kardinalität <code>0..1</code>, Stereotyp <code>«input»</code>): Optionale Spezifikation der Interaktionsschicht / Kommunikationsbeziehungen.</li>\n<li><strong>Ausgangs-Artefakt</strong>:</li>\n<li><code>Network Layer</code> (Stereotyp <code>«output»</code>): Konfigurationsartefakt bzw. Teilmodell der Netzwerkschicht inklusive Network-Management-Parametern.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der <code>System Engineer</code> führt die Aktivität <code>Define Network Management</code> aus.</li>\n<li>Als zwingende Eingangsgröße wird genau eine Instanz der <code>Topology</code> herangezogen (<code>1 «input»</code>).</li>\n<li>Optional kann eine Spezifikation des <code>Interaction Layer</code> (<code>0..1 «input»</code>) eingebunden werden.</li>\n<li>Als Resultat der Aktivität wird das Artefakt <code>Network Layer</code> erzeugt (<code>«output»</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Kardinalität <code>1</code> fordert das Vorhandensein einer definierten Topologie als zwingende Voraussetzung für die Konfiguration des Network Managements. Das Artefakt <code>Interaction Layer</code> ist mit <code>0..1</code> optional, wodurch eine Festlegung des Network Managements auch vor oder unabhängig von detaillierten Interaktionsschicht-Parametern methodisch zulässig ist. Das resultierende Artefakt <code>Network Layer</code> bildet die Grundlage für nachgelagerte ECU-Extraktions- und Generierungsschritte im AUTOSAR-Workflow.</p>"}], "trans": [{"from": "FIG-5c2ac585f1c694ce", "to": "FIG-0629dc981f72def3", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
